dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "parameter": "phenotype",
      "label": "Phenotype",
      "type": "list",
      "values": "kp phenotypes"
    },
    {
      "parameter": "ancestry",
      "label": "Ancestry",
      "type": "list",
      "values": [
        {
          "label": "Mixed",
          "value": "*"
        },
        {
          "label": "African American or Afro-Caribbean",
          "value": "AA"
        },
        {
          "label": "Greater Middle Eastern (Middle Eastern, North African, or Persian)",
          "value": "GME"
        },
        {
          "label": "Sub-Saharan African",
          "value": "SSAF"
        },
        {
          "label": "African unspecified",
          "value": "AF"
        },
        {
          "label": "East Asian",
          "value": "EA"
        },
        {
          "label": "South Asian",
          "value": "SA"
        },
        {
          "label": "European",
          "value": "EU"
        }
      ]
    },
    {
      "parameter": "region",
      "label": "Region by",
      "type": "input",
      "values": "kp genes",
      "convert to region": "true",
      "expand region by": 100000,
      "display": "false"
    },
    {
      "parameter": "csid",
      "label": "Credible Sets ID",
      "type": "input",
      "display": "false"
    },
    {
      "parameter": "tissue",
      "label": "Tissue",
      "type": "input",
      "display": "false"
    },
    {
      "parameter": "cvPhenotype",
      "label": "cvPhenotype",
      "type": "input",
      "display": "false"
    },
    {
      "parameter": "clump",
      "label": "clump",
      "type": "input",
      "display": "false"
    }
  ],
  "tab groups": [
    {
      "label": "Find Region of Interest",
      "sections": [
        {
          "section": "c2ct",
          "label": "CS2CT"
        }
      ]
    },
    {
      "label": "credible variants",
      "sections": [
        {
          "section": "credible_variants",
          "label": "Variants in credible set"
        },
        {
          "section": "credible_sets",
          "label": "Other credible sets in region"
        }
      ]
    },
    {
      "label": "Variants",
      "sections": [
        {
          "section": "associations",
          "label": "Variants in CS region +-200K"
        }
      ]
    },
    {
      "label": "Annotated regions",
      "sections": [
        {
          "section": "regions",
          "label": "Annotated regions"
        }
      ]
    },
    {
      "label": "Data summary",
      "type": "fixed bottom",
      "sections": [
        {
          "section": "page_summary",
          "label": "Variants in region filtered by CS variants overlapping with annotated regions"
        }
      ]
    }
  ],
  "sections": [
    {
      "section id": "c2ct",
      "header": "CS2CT tissue",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex-dev.hugeamp.org/api/bio/",
        "index": "c2ct",
        "parameters": [
          "phenotype",
          "ancestry"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Biosample",
            "raw field": "biosample"
          },
          {
            "type": "raw",
            "field name": "Source",
            "raw field": "source"
          },
          {
            "type": "raw",
            "field name": "CS ID",
            "raw field": "credibleSetId"
          },
          {
            "type": "raw",
            "field name": "chromosome",
            "raw field": "chromosome"
          },
          {
            "type": "calculate",
            "calculation type": "math",
            "field name": "region length",
            "expression": [
              "clumpEnd",
              "-",
              "clumpStart"
            ],
            "note": "required to get clumped region center"
          },
          {
            "type": "join multi",
            "field name": "CS region (length)",
            "fields to join": [
              "chromosome",
              "clumpStart",
              "clumpEnd",
              "region length"
            ],
            "join by": [
              ":",
              "-",
              " (",
              "bp)"
            ]
          },
          {
            "type": "join multi",
            "field name": "CS region",
            "fields to join": [
              "chromosome",
              "clumpStart",
              "clumpEnd"
            ],
            "join by": [
              ":",
              "-"
            ]
          },
          {
            "type": "calculate",
            "calculation type": "math",
            "field name": "region center",
            "expression": [
              "(",
              "clumpStart",
              "+",
              "clumpEnd",
              ")",
              "/",
              2
            ],
            "note": "required to get clumped region center"
          },
          {
            "type": "js math",
            "field name": "regionCenterRounded",
            "raw field": "region center",
            "method": "round"
          },
          {
            "type": "calculate",
            "calculation type": "math",
            "field name": "regionStart",
            "expression": [
              "regionCenterRounded",
              "-",
              200000
            ],
            "min number": 0,
            "note": ""
          },
          {
            "type": "calculate",
            "calculation type": "math",
            "field name": "regionEnd",
            "expression": [
              "regionCenterRounded",
              "+",
              200000
            ],
            "note": ""
          },
          {
            "type": "join multi",
            "field name": "View variants in CS & CS region +-200kb",
            "fields to join": [
              "CS ID",
              "chromosome",
              "regionStart",
              "regionEnd"
            ],
            "join by": [
              ",",
              ":",
              "-"
            ]
          },
          {
            "type": "raw",
            "field name": "PPO",
            "raw field": "posteriorProbability",
            "if no value": 0
          },
          {
            "type": "raw",
            "field name": "Total entropy",
            "raw field": "totalEntropy",
            "if no value": 0
          },
          {
            "type": "raw",
            "field name": "Entropy",
            "raw field": "entropy",
            "if no value": 0
          },
          {
            "type": "raw",
            "field name": "Q",
            "raw field": "Q",
            "if no value": 0
          },
          {
            "type": "join multi",
            "field name": "Biosample:CS region",
            "fields to join": [
              "Biosample",
              "CS region"
            ],
            "join by": [
              ":"
            ]
          },
          {
            "type": "raw",
            "field name": "Annotation",
            "raw field": "annotation",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "Annotation bp",
            "raw field": "annot_bp",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "Entropy PP",
            "raw field": "entPP",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "Entropy type",
            "raw field": "entropyType",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "Lead SNP",
            "raw field": "leadSNP",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "Overlap lead SNP",
            "raw field": "overlapLeadSNP",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "Overlapping variants",
            "raw field": "varOverlap",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "Variant total",
            "raw field": "varTotal",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "Tissue",
            "raw field": "tissue"
          }
        ],
        "top rows": [
          "Tissue",
          "Biosample",
          "Source",
          "CS ID",
          "CS region (length)",
          "Lead SNP",
          "PPO",
          "Entropy",
          "View variants in CS & CS region +-200kb"
        ],
        "column formatting": {
          "CS ID": {
            "type": [
              "shorten"
            ],
            "shorten to": 10,
            "shorten anchor": "end"
          },
          "PPO": {
            "type": [
              "scientific notation"
            ]
          },
          "Entropy": {
            "type": [
              "scientific notation"
            ]
          },
          "Total entropy": {
            "type": [
              "scientific notation"
            ]
          },
          "Q": {
            "type": [
              "scientific notation"
            ]
          },
          "View variants in CS & CS region +-200kb": {
            "type": [
              "set parameter"
            ],
            "label": "Load variants",
            "target sections": [
              {
                "section": "all",
                "label": "Set CS ID & CS region",
                "parameter": [
                  "csid",
                  "region"
                ]
              }
            ]
          }
        },
        "features": [
          "Anno",
          "Var",
          "Ent"
        ],
        "features header": "More info",
        "Anno": [
          "Annotation",
          "Annotation bp"
        ],
        "Var": [
          "Lead SNP",
          "Overlap lead SNP",
          "Overlapping variants",
          "Variant total"
        ],
        "Ent": [
          "Entropy",
          "Entropy PP",
          "Entropy type",
          "Total entropy"
        ]
      },
      "filters": [
        {
          "field": "Annotation",
          "label": "Annotation",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "chromosome",
          "label": "Chromosome",
          "type": "search",
          "label in bubble": "true"
        },
        {
          "field": "Tissue",
          "label": "Tissue",
          "type": "search",
          "features": [
            "autocomplete"
          ],
          "label in bubble": "true"
        },
        {
          "field": "Source",
          "label": "Source",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "PPO",
          "label": "PPO(>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Entropy",
          "label": "Entropy(<=)",
          "type": "search lower than",
          "label in bubble": "true"
        }
      ],
      "visualizer": {
        "label": "",
        "type": "scatter plot",
        "star key": "Biosample:CS region",
        "render type": "single plot",
        "group by": "Phenotype",
        "color by": "Source",
        "x axis field": "Entropy",
        "x axis label": "Entropy",
        "y axis field": "PPO",
        "y axis label": "PPO",
        "ticks decimal point": "4",
        "render by": "Biosample:CS region",
        "hover content": [
          "PPO",
          "Entropy",
          "Total entropy",
          "Q"
        ],
        "height": 150,
        "width": 450,
        "plot margin": {
          "left": 60,
          "right": 20,
          "top": 40,
          "bottom": 50,
          "bump": 5
        }
      }
    },
    {
      "section id": "credible_sets",
      "header": "Credible Sets",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex-dev.hugeamp.org/api/bio/",
        "index": "credible-sets",
        "parameters": [
          "phenotype",
          "ancestry",
          "region"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "CS ID",
            "raw field": "credibleSetId"
          },
          {
            "type": "join multi",
            "field name": "CS region",
            "fields to join": [
              "chromosome",
              "start",
              "end"
            ],
            "join by": [
              ":",
              "-"
            ]
          },
          {
            "type": "calculate",
            "calculation type": "math",
            "field name": "region length",
            "expression": [
              "end",
              "-",
              "start"
            ],
            "note": "required to get clumped region center"
          },
          {
            "type": "join multi",
            "field name": "CS region (length)",
            "fields to join": [
              "CS region",
              "region length"
            ],
            "join by": [
              " (",
              "bp)"
            ]
          },
          {
            "type": "raw",
            "field name": "Dataset",
            "raw field": "dataset"
          },
          {
            "type": "raw",
            "field name": "Method",
            "raw field": "method"
          },
          {
            "type": "raw",
            "field name": "PMID",
            "raw field": "pmid"
          }
        ],
        "top rows": [
          "CS ID",
          "CS region (length)",
          "Dataset",
          "Method",
          "PMID"
        ],
        "column formatting": {
          "CS ID": {
            "type": [
              "set parameter"
            ],
            "target sections": [
              {
                "section": "all",
                "label": "Load variants to CS variants table",
                "parameter": [
                  "csid"
                ]
              }
            ]
          }
        }
      },
      "filters": [
        {
          "field": "Dataset",
          "label": "Dataset",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "Method",
          "label": "Method",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "PMID",
          "label": "PMID",
          "type": "checkbox",
          "label in bubble": "true"
        }
      ]
    },
    {
      "section id": "credible_variants",
      "header": "Credible Variants",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex-dev.hugeamp.org/api/bio/",
        "index": "credible-variants",
        "parameters": [
          "phenotype",
          "ancestry",
          "csid"
        ],
        "cumulate data": "true",
        "parameters type": "array",
        "data type": "bioindex",
        "region": "region"
      },
      "table format": {
        "data convert": [
          {
            "type": "join multi",
            "field name": "Variant ID",
            "fields to join": [
              "chromosome",
              "position",
              "reference",
              "alt"
            ],
            "join by": [
              ":",
              "_",
              "/"
            ]
          },
          {
            "type": "raw",
            "field name": "CV Variant ID",
            "raw field": "Variant ID"
          },
          {
            "type": "join multi",
            "field name": "Ref/Alt",
            "fields to join": [
              "reference",
              "alt"
            ],
            "join by": [
              "/"
            ]
          },
          {
            "type": "raw",
            "field name": "PPO",
            "raw field": "posteriorProbability"
          },
          {
            "type": "raw",
            "field name": "CS ID",
            "raw field": "credibleSetId"
          },
          {
            "type": "raw",
            "field name": "Dataset",
            "raw field": "dataset"
          },
          {
            "type": "raw",
            "field name": "Method",
            "raw field": "method"
          },
          {
            "type": "raw",
            "field name": "PMID",
            "raw field": "pmid"
          },
          {
            "type": "raw",
            "field name": "Position",
            "raw field": "position"
          }
        ],
        "top rows": [
          "Variant ID",
          "PPO",
          "CS ID",
          "Dataset",
          "Method",
          "Position",
          "PMID"
        ],
        "locus field": "CS region",
        "star column": "Variant ID",
        "column formatting": {
          "PPO": {
            "type": [
              "scientific notation"
            ]
          }
        }
      },
      "filters": [
        {
          "field": "PPO",
          "label": "PPO(>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Dataset",
          "label": "Dataset",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "Method",
          "label": "Method",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "PMID",
          "label": "PMID",
          "type": "checkbox",
          "label in bubble": "true"
        }
      ]
    },
    {
      "section id": "associations",
      "header": "Variants in Credible set region",
      "search parameters": [
        {
          "parameter": "region",
          "label": "Region (chr:start-end or gene)",
          "type": "input",
          "values": "kp genes",
          "convert to region": "true",
          "expand region by": 100000
        }
      ],
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex-dev.hugeamp.org/api/bio/query/associations?q=$phenotype,$region",
        "continue url": "https://bioindex-dev.hugeamp.org/api/bio/cont?limit=20000&token=",
        "parameters": [
          "phenotype",
          "region"
        ],
        "parameters type": "replace",
        "data type": "bioindex"
      },
      "table format": {
        "data zoom": {
          "chromosome": "chromosome",
          "position": "Position"
        },
        "initial sort by": {
          "field": "P-Value",
          "type": "number",
          "direction": "desc"
        },
        "data convert": [
          {
            "type": "raw",
            "field name": "chromosome",
            "raw field": "chromosome"
          },
          {
            "type": "raw",
            "field name": "Position",
            "raw field": "position"
          },
          {
            "type": "raw",
            "field name": "ref",
            "raw field": "reference"
          },
          {
            "type": "raw",
            "field name": "alt",
            "raw field": "alt"
          },
          {
            "type": "raw",
            "field name": "Beta",
            "raw field": "beta",
            "if no value": 0
          },
          {
            "type": "raw",
            "field name": "MAF",
            "raw field": "maf",
            "if no value": 0
          },
          {
            "type": "raw",
            "field name": "Standard error",
            "raw field": "stdErr",
            "if no value": 0
          },
          {
            "type": "raw",
            "field name": "Consequence",
            "raw field": "consequence"
          },
          {
            "type": "raw",
            "field name": "Z Score",
            "raw field": "zScore",
            "if no value": 0
          },
          {
            "type": "raw",
            "field name": "P-Value",
            "raw field": "pValue",
            "if no value": 0
          },
          {
            "type": "raw",
            "field name": "rsID",
            "raw field": "dbSNP"
          },
          {
            "type": "join",
            "field name": "Ref/Alt",
            "fields to join": [
              "reference",
              "alt"
            ],
            "join by": "/"
          },
          {
            "type": "join",
            "field name": "Locus",
            "fields to join": [
              "chromosome",
              "position"
            ],
            "join by": ":"
          },
          {
            "type": "join multi",
            "field name": "Variant ID",
            "fields to join": [
              "chromosome",
              "position",
              "reference",
              "alt"
            ],
            "join by": [
              ":",
              "_",
              "/"
            ]
          },
          {
            "type": "join multi",
            "field name": "KP Variant ID",
            "fields to join": [
              "chromosome",
              "position",
              "reference",
              "alt"
            ],
            "join by": [
              ":",
              ":",
              ":"
            ]
          },
          {
            "type": "raw",
            "field name": "chr",
            "raw field": "chromosome"
          },
          {
            "type": "calculate",
            "field name": "-log10(P-Value)",
            "raw field": "pValue",
            "calculation type": "-log10"
          }
        ],
        "top rows": [
          "Variant ID",
          "rsID",
          "Ref/Alt",
          "P-Value",
          "Beta",
          "MAF",
          "Standard error",
          "Z Score",
          "Consequence"
        ],
        "star column": "Variant ID",
        "locus field": "Locus",
        "column formatting": {
          "PPO": {
            "type": [
              "scientific notation"
            ]
          },
          "P-Value": {
            "type": [
              "scientific notation"
            ]
          },
          "Odds Ratio": {
            "type": [
              "scientific notation"
            ]
          },
          "Beta": {
            "type": [
              "scientific notation"
            ]
          },
          "EAF": {
            "type": [
              "scientific notation"
            ]
          },
          "MAF": {
            "type": [
              "scientific notation"
            ]
          },
          "Standard error": {
            "type": [
              "scientific notation"
            ]
          },
          "Z Score": {
            "type": [
              "scientific notation"
            ]
          },
          "Target Gene": {
            "type": [
              "link"
            ],
            "link to": "/gene.html?gene=",
            "new tab": "true"
          }
        }
      },
      "pre filters not": [
        {
          "field": "P-Value",
          "value": 0.05,
          "parameter": "pValue",
          "type": "search lower than"
        }
      ],
      "filters": [
        {
          "field": "Variant ID",
          "label": "Variant ID",
          "type": "search",
          "features": [
            "autocomplete"
          ],
          "label in bubble": "true"
        },
        {
          "field": "rsID",
          "label": "rsID",
          "type": "search",
          "features": [
            "autocomplete"
          ],
          "label in bubble": "true"
        },
        {
          "field": "P-Value",
          "label": "P-Value (<=)",
          "type": "search lower than",
          "label in bubble": "true"
        },
        {
          "field": "Beta",
          "label": "Beta (>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Z Score",
          "label": "Z Score (>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Consequence",
          "label": "Consequence",
          "type": "dropdown",
          "label in bubble": "true"
        }
      ],
      "filter width": "sm",
      "visualizer": {
        "star key": "Variant ID",
        "zoom": "true",
        "type": "region plot",
        "x axis field": "Position",
        "y axis field": "-log10(P-Value)",
        "render by": "Variant ID",
        "y axis label": "-Log10(p-value)",
        "x axis label": "Chromosome",
        "hover content": [
          "P-Value",
          "Beta"
        ],
        "height": 120,
        "plot margin": {
          "left": 200,
          "right": 200,
          "top": 30,
          "bottom": 100,
          "bump": 10
        },
        "ld server": {
          "pos": "Position",
          "ref": "ref",
          "alt": "alt",
          "ref variant field": "Variant ID",
          "populations field": "P-Value",
          "populations type": "fixed",
          "fixed population": "ALL",
          "populations": {
            "ALL": "ALL"
          }
        },
        "genes track": {
          "input type": "dynamic",
          "dynamic parameter": "region"
        },
        "input type": "dynamic",
        "dynamic parameter": "region",
        "if combine y axis field": {
          "type": "average",
          "field": "-log10(P-Value)"
        }
      }
    },
